const screen=document.querySelector('#screen');
const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const objects=[
 {id:1,name:'Garrafa verde',place:'Biblioteca',date:'2026-10-20',description:'Garrafa térmica verde encontrada em uma mesa de estudo.',pickup:'Balcão da Biblioteca'},
 {id:2,name:'Caderno azul',place:'Sala 102',date:'2026-10-19',description:'Caderno de espiral azul encontrado após a aula.',pickup:'Secretaria'},
 {id:3,name:'Chave com chaveiro',place:'Cantina',date:'2026-10-19',description:'Chave com um chaveiro preto encontrada perto do balcão.',pickup:'Balcão da Cantina'}
];
let lastSearch='',registered=false;
const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const formatDate=s=>s.split('-').reverse().join('/');
function list(){screen.innerHTML='<h1>Objetos encontrados</h1><p>Procure seu objeto na lista abaixo.</p>'+(registered?'<p class="success" role="status">Objeto cadastrado nesta demonstração.</p>':'')+'<label class="search-label" for="search">Buscar objeto</label><input id="search" type="search" placeholder="Ex.: garrafa" value="'+escapeHtml(lastSearch)+'"><p class="count" id="count" role="status"></p><ul class="list" id="items"></ul><div class="toolbar"><a class="button secondary" href="#cadastro">Cadastrar objeto encontrado</a></div>';registered=false;const input=document.querySelector('#search');function filter(){lastSearch=input.value;const found=objects.filter(o=>normalize(o.name+' '+o.place).includes(normalize(lastSearch.trim())));document.querySelector('#count').textContent=found.length+' objeto(s) na lista';document.querySelector('#items').innerHTML=found.length?found.map(o=>'<li class="item"><h2>'+escapeHtml(o.name)+'</h2><p>Encontrado em: '+escapeHtml(o.place)+'</p><a href="#objeto/'+o.id+'" aria-label="Ver detalhes de '+escapeHtml(o.name)+'">Ver detalhes</a></li>').join(''):'<li class="empty">Nenhum objeto encontrado. Tente outro nome.</li>';}input.oninput=filter;filter();}
function detail(id){const o=objects.find(o=>o.id===Number(id));if(!o){location.hash='';return;}screen.innerHTML='<a class="back" href="#">Voltar à lista</a><h1>'+escapeHtml(o.name)+'</h1><dl class="details"><dt>Onde foi encontrado</dt><dd>'+escapeHtml(o.place)+'</dd><dt>Data</dt><dd>'+formatDate(o.date)+'</dd><dt>Descrição</dt><dd>'+escapeHtml(o.description)+'</dd><dt>Onde retirar</dt><dd>'+escapeHtml(o.pickup)+'</dd></dl><p>Se o objeto for seu, procure o atendimento no local indicado.</p><p class="note">Exemplo fictício. Não há retirada real.</p>';}
function register(){screen.innerHTML='<a class="back" href="#">Voltar à lista</a><h1>Cadastrar objeto encontrado</h1><p>Preencha os dados do objeto que você encontrou.</p><form id="form" novalidate><label for="name">Nome do objeto</label><input id="name" name="name" required maxlength="70" aria-describedby="name-error"><p class="error" id="name-error" hidden></p><label for="place">Onde foi encontrado?</label><input id="place" name="place" required maxlength="100" aria-describedby="place-error"><p class="error" id="place-error" hidden></p><label for="description">Descrição</label><textarea id="description" name="description" required maxlength="400" aria-describedby="description-error"></textarea><p class="error" id="description-error" hidden></p><p class="note">Nesta demonstração, a retirada será na Secretaria.</p><button class="submit" type="submit">Cadastrar objeto</button><p class="note">Cadastro de teste. Os dados desaparecem ao atualizar a página.</p></form>';document.querySelector('#form').onsubmit=e=>{e.preventDefault();const fields=[...e.target.querySelectorAll('[required]')];let first=null;fields.forEach(f=>{const error=document.querySelector('#'+f.id+'-error'),invalid=!f.value.trim();error.hidden=!invalid;error.textContent=invalid?'Preencha este campo.':'';f.setAttribute('aria-invalid',String(invalid));if(invalid&&!first)first=f;});if(first){first.focus();return;}const d=new Date();const date=[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');objects.unshift({id:Date.now(),name:fields[0].value.trim(),place:fields[1].value.trim(),description:fields[2].value.trim(),date,pickup:'Secretaria'});lastSearch='';registered=true;location.hash='';};}
function route(){const hash=location.hash.slice(1);if(hash==='cadastro')register();else if(hash.startsWith('objeto/'))detail(hash.split('/')[1]);else list();const h=screen.querySelector('h1');h.tabIndex=-1;h.focus({preventScroll:true});window.scrollTo(0,0);}
window.addEventListener('hashchange',route);route();
